package br.com.onda;
import android.content.*;import android.graphics.*;import android.net.Uri;import android.os.Build;import android.provider.MediaStore;import java.io.*;import java.util.*;
/** AI writes the message; native artwork composes the card. No diffusion model is implied. */
final class LocalAiArt {
 static File folder(Context c){File dir=new File(c.getCacheDir(),"shares/ai");dir.mkdirs();File[] old=dir.listFiles();if(old!=null)for(File f:old)if(System.currentTimeMillis()-f.lastModified()>48L*60*60*1000)f.delete();return dir;}
 static File card(Context c,String theme,String message,int style)throws IOException{return card(c,theme,message,style,null,new LocalAiModels.Cancel());}
 static File card(Context c,String theme,String message,int style,android.net.Uri photo,LocalAiModels.Cancel cancel)throws IOException{String title=theme.trim().replaceFirst("(?iu)^(?:(?:crie|gere|faça|escreva)\\s+)?(?:um[a]?\\s+)?(?:cart[aã]o|mensagem)\\s+(?:de|sobre|para)\\s+","");if(title.length()>40)title=title.substring(0,40);String copy=message.trim();if(copy.length()>650)copy=copy.substring(0,650);if(copy.isEmpty())throw new IOException("A IA não concluiu a mensagem do cartão.");Bitmap bitmap=photo==null?MessageCardArt.draw(title,copy,style,720):photoCard(c,photo,title,copy,cancel);File output=new File(folder(c),"Onda-IA-"+UUID.randomUUID()+".png");boolean complete=false;try(OutputStream out=new FileOutputStream(output)){if(!bitmap.compress(Bitmap.CompressFormat.PNG,100,out))throw new IOException("Não foi possível criar o cartão.");complete=true;return output;}finally{bitmap.recycle();if(!complete)output.delete();}}
 static Bitmap photoCard(Context c,android.net.Uri photo,String title,String message,LocalAiModels.Cancel cancel)throws IOException{Bitmap source=LocalAiPhotos.load(c,photo,1280,cancel);Bitmap result=null;try{int width=720,height=900;result=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(result);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);float scale=Math.max(width/(float)source.getWidth(),height/(float)source.getHeight()),w=source.getWidth()*scale,h=source.getHeight()*scale;canvas.drawBitmap(source,null,new RectF((width-w)/2,(height-h)/2,(width+w)/2,(height+h)/2),paint);paint.setShader(new LinearGradient(0,height*.2f,0,height,new int[]{0x11000000,0xdd000000},null,Shader.TileMode.CLAMP));canvas.drawRect(0,0,width,height,paint);android.text.TextPaint text=new android.text.TextPaint(Paint.ANTI_ALIAS_FLAG);text.setColor(Color.WHITE);text.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));text.setTextSize(36);android.text.StaticLayout heading=android.text.StaticLayout.Builder.obtain(title,0,title.length(),text,624).setAlignment(android.text.Layout.Alignment.ALIGN_CENTER).setIncludePad(false).build();text=new android.text.TextPaint(text);text.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));android.text.StaticLayout body=null;for(int size=30;size>=18;size-=2){text.setTextSize(size);body=android.text.StaticLayout.Builder.obtain(message,0,message.length(),text,624).setAlignment(android.text.Layout.Alignment.ALIGN_CENTER).setIncludePad(false).setLineSpacing(6,1.05f).build();if(body.getHeight()+heading.getHeight()<height*.58)break;}int top=Math.max(42,height-70-heading.getHeight()-body.getHeight()-24);canvas.save();canvas.translate(48,top);heading.draw(canvas);canvas.translate(0,heading.getHeight()+24);body.draw(canvas);canvas.restore();cancel.check();return result;}catch(IOException|RuntimeException|OutOfMemoryError e){if(result!=null)result.recycle();if(e instanceof IOException)throw (IOException)e;throw new IOException("Não foi possível compor o cartão com esta foto.",e);}finally{source.recycle();}}
 static Uri save(Context c,File source,String mime,LocalAiModels.Cancel cancel)throws IOException{if(Build.VERSION.SDK_INT<29)throw new IOException("Use o seletor de arquivos do Android para salvar neste aparelho.");boolean video=mime.equals("video/mp4");ContentValues values=new ContentValues();values.put(MediaStore.MediaColumns.DISPLAY_NAME,source.getName());values.put(MediaStore.MediaColumns.MIME_TYPE,mime);values.put(MediaStore.MediaColumns.RELATIVE_PATH,(video?"Movies/":"Pictures/")+"Onda/IA");values.put(MediaStore.MediaColumns.IS_PENDING,1);Uri uri=c.getContentResolver().insert(video?MediaStore.Video.Media.EXTERNAL_CONTENT_URI:MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new IOException("Não foi possível criar o arquivo na pasta do Onda.");boolean done=false;try{try(OutputStream out=c.getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("Pasta indisponível");copy(source,out,cancel);}cancel.check();values.clear();values.put(MediaStore.MediaColumns.IS_PENDING,0);c.getContentResolver().update(uri,values,null,null);done=true;return uri;}finally{if(!done)c.getContentResolver().delete(uri,null,null);}}
 static void copy(File source,OutputStream out,LocalAiModels.Cancel cancel)throws IOException{try(InputStream in=new FileInputStream(source)){byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1){cancel.check();out.write(b,0,n);}}}
}
